export function pairWithTarget(nums, target) {
  const seen = new Map();
  for (let j = 0; j < nums.length; j++) {
    const partner = target - nums[j];
    if (seen.has(partner)) return [seen.get(partner), j];
    seen.set(nums[j], j);
  }
  return [];
}
